fn find_first_occurrence(arr: &Vec<i32>, target: i32) -> Option<usize> {
    let mut left = 0usize;
    let mut right = arr.len();
    // Binary search to find the first occurrence of target in sorted arr
    while left < right {
        let mid = left + (right - left) / 2;
        if arr[mid] < target {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    if left < arr.len() && arr[left] == target {
        Some(left)
    } else {
        None
    }
}